esc=lambda s:html.escape(str(s));money=lambda n:f'${float(n):.2f}'
summary=[];cards=[];md=['# Atelier Veyne — 10 bags + 10 wallets','Research date: 27 October 2026','','370 unique catalog records collected across both search rounds; 103 thumbnail placements visually screened (including repeats), 25 detailed product records with representative US/UK freight checks. This is a researched sample shortlist, not a certification of product quality.','','Quotes are for ONE specified variant and ONE item from China, without postcode. Other variants and addresses require new quotes. Product + quoted postage is not a complete landed cost; unquoted VAT, duties, taxes, handling, payment fees, returns and advertising are excluded. Transit estimates are CJ quotes, not delivery promises; supplier processing time is not verified.','','All selected products are outside the saved local catalog of 31 CJ products. No CJ saved-product, Shopify listing, inventory or shipping settings were changed.','']
for kind,indices in [('Bags',bags),('Wallets',wallets)]:
 md+=['## '+kind,'','| Product | CJ SKU | Selected variant | Supplier USD | US postage / total USD | UK postage / total USD |','|---|---|---|---:|---:|---:|'];section=[]
 for rank,k in enumerate(indices,1):
  i=by[k];v=i['checkedVariant'];title,material,note=notes[k];cost=float(v['variantSellPrice']);assert str(i['product']['pid']) not in saved
  quote={}
  for country in ['US','GB']:
   methods=[q for q in i['quotes'][country] if q.get('logisticPrice') is not None and not q.get('error') and not q.get('errorEn')]
   assert methods, (k,country)
   methods.sort(key=lambda q:float(q.get('totalPostageFee') if q.get('totalPostageFee') is not None else q['logisticPrice']));q=methods[0];post=float(q.get('totalPostageFee') if q.get('totalPostageFee') is not None else q['logisticPrice']);assert post>=0
   quote[country]={'postage':post,'productPlusPostage':round(cost+post,2),'method':q['logisticName'],'transitEstimate':q['logisticAging']}
  st=stocks.get(str(k),{});assert st.get('data'),(k,'missing inventory');inventory=st['data'];selected=next((x for x in inventory.get('variantInventories',[]) if str(x['vid'])==str(v['vid'])),None);assert selected, (k,'missing variant inventory');cn=[x for x in selected['inventory'] if x['countryCode']=='CN'];assert cn and sum(int(x.get('totalInventory',0)) for x in cn)>0,(k,'no origin stock')
  cjstock=sum(int(x.get('cjInventory',0)) for x in cn);factory=sum(int(x.get('factoryInventory',0)) for x in cn);stock=f'Selected variant, China: {cjstock:,} CJ warehouse units; {factory:,} supplier/factory units reported. Supplier stock is not physically verified by this review.'
  path=root/f'expanded-thumbs/{k}.jpg'
  if not path.exists():
   path=root/f'thumbs/{k}.jpg'
  assert path.exists(),(k,'photo')
  rel=str(path.relative_to(root));sku=i['candidate']['sku'];md.append(f'| {title} | {sku} | {v["variantKey"]} | {money(cost)} | {money(quote["US"]["postage"])} / {money(quote["US"]["productPlusPostage"])} | {money(quote["GB"]["postage"])} / {money(quote["GB"]["productPlusPostage"])} |')
  row={'kind':kind,'rank':rank,'title':title,'sku':sku,'cjProductId':str(i['product']['pid']),'checkedVariantId':str(v['vid']),'checkedVariantSku':v['variantSku'],'checkedVariant':v['variantKey'],'supplierPrice':cost,'materialClaim':material,'review':note,'quotes':quote,'inventory':{'cjWarehouseCN':cjstock,'supplierFactoryCN':factory},'photo':rel,'alreadySaved':False};summary.append(row)
  route=''.join(f'<tr><td>{label}</td><td>{money(quote[c]["postage"])}</td><td>{money(quote[c]["productPlusPostage"])}</td></tr>' for c,label in [('US','US'),('GB','UK')]);details=''.join(f'<p>{label}: {esc(quote[c]["method"])} · transit estimate {esc(quote[c]["transitEstimate"])}</p>' for c,label in [('US','US'),('GB','UK')])
  section.append(f'<article><div class="photo"><img loading="lazy" src="{rel}" alt="Original CJ catalog photo for {esc(title)}"><span>Original CJ photo</span></div><div class="content"><small>{kind[:-1] if kind=="Bags" else "Wallet"} {rank:02d} · {esc(sku)}</small><h3>{esc(title)}</h3><p class="price">{money(cost)} <span>supplier price</span></p><p>{esc(note)}</p><p class="material">Supplier material claim: {esc(material)}</p><p class="muted">Quoted variant: {esc(v["variantKey"])}. Main catalog photo may show another color.</p><table><thead><tr><th>Destination</th><th>Postage</th><th>Product + postage</th></tr></thead><tbody>{route}</tbody></table><details><summary>Shipping, inventory & source details</summary>{details}<p>{esc(stock)}</p><p>Product ID: {esc(i["product"]["pid"])}</p><p>Variant SKU: {esc(v["variantSku"])}</p><p>All {len(i["product"]["variants"])} source variants retained in research. Only the variant named above was freight-checked.</p></details></div></article>')
 cards.append(f'<section id="{kind.lower()}"><h2>{len(indices)} {kind.lower()}</h2><div class="grid">'+''.join(section)+'</div></section>')
 md+=['']
md+=['## Material and sample review notes','']
for x in summary:md+=['- **'+x['sku']+'** — '+x['materialClaim']+'. '+x['review']]
