css='''*{box-sizing:border-box}body{margin:0;background:#f5f1ea;color:#1b1a18;font:15px/1.6 system-ui}main{max-width:1360px;margin:auto;padding:42px 24px 80px}h1,h2,h3{font-family:Georgia,serif;font-weight:400}h1{font-size:clamp(38px,6vw,68px);line-height:1.1;max-width:820px}h2{font-size:36px;margin:44px 0 20px}h3{font-size:27px;line-height:1.2;margin:10px 0}header>p{max-width:920px}small{color:#9a4f36;letter-spacing:.08em;font-size:11px;text-transform:uppercase}.nav{display:flex;gap:12px;margin:28px 0;flex-wrap:wrap}.nav a{padding:10px 20px;background:#1b1a18;color:#f5f1ea;text-decoration:none}.notice{padding:18px 22px;border:1px solid #d9d0c3;background:#ece5da}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}article{background:#fffdf8;border:1px solid #d9d0c3;overflow:hidden}.photo{position:relative;background:white;height:330px;padding:12px}.photo img{width:100%;height:100%;object-fit:contain}.photo span{position:absolute;bottom:10px;left:12px;background:#fffdf8de;padding:3px 8px;font-size:11px;color:#6b6258}.content{padding:25px}.price{font-size:24px;margin:12px 0}.price span{font:13px system-ui;color:#6b6258}.muted,details{font-size:13px;color:#6b6258}.material{font-size:13px;border-left:2px solid #9a4f36;padding-left:12px}table{width:100%;border-collapse:collapse;font-size:13px;margin:20px 0}th,td{padding:10px 6px;text-align:left;border-bottom:1px solid #d9d0c3}th{font-size:11px;color:#6b6258}summary{cursor:pointer;color:#1b1a18}details p{overflow-wrap:anywhere}footer{margin-top:40px;font-size:13px;color:#6b6258}a{color:inherit}@media(max-width:700px){main{padding:26px 16px}.grid{grid-template-columns:1fr}.photo{height:300px}.content{padding:20px}}'''
intro='''<header><small>ATELIER VEYNE · CJ SOURCING REVIEW · 27 OCTOBER 2026</small><h1>Considered bags.<br>Everyday wallets.</h1><p>10 bags + 10 wallets selected for understated shapes, a useful color range and price. All have current one-item shipping estimates to the US and UK for a named variant. These are sample candidates; physical quality is not verified.</p><div class="nav"><a href="#bags">10 bags · $16.25–24.51</a><a href="#wallets">10 wallets · $5.05–9.95</a><a href="SHORTLIST.md">Full research notes</a></div><div class="notice"><strong>Read the totals correctly.</strong> USD throughout. Estimates ship from China, not a US/UK warehouse. Product + postage excludes unquoted taxes, duties and business costs. Quotes have no postcode and apply to one named variant; other colors and addresses can differ. Most stock is supplier/factory-reported. CJ transit estimates are not delivery guarantees and processing time remains unverified. Nothing added to CJ or Shopify.</div><p><strong>First samples:</strong> bags CJNS3126023, CJNS3181599, CJNS2968091; wallets CJNS2042296, CJNS2796968, CJNS1970625. Neutral colorways fit the store best.</p></header>'''
(root/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atelier Veyne · 10 bags + 10 wallets</title><style>'+css+'</style></head><body><main>'+intro+''.join(cards)+'<footer>Source: live authenticated CJ catalog, product details, inventory and freight estimates. Original supplier photos are retained for review. Material statements remain supplier claims, and sample inspection is needed before listing. Search the exact CJ SKU to find each item in CJ.</footer></main></body></html>')
